Event Start
LoadWWPContext.Call(&WWPContext) &prefCodigo = &WWPContext.prefCodigo
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do 'LoadVariablesFromWizardData' &DataInicial.Visible = False &DataFinal.Visible = False
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
if &Ano.IsEmpty() &Ano = year(serverdate()) endif
if &Mes.IsEmpty() &Mes = Meses.Convert(month(serverdate())) endif
if &DataEnvio.IsEmpty() &DataEnvio = serverdate() endif
if &Ano.Count = 0 &Ano.AddItem(&Ano,&Ano.ToString()) if &Mes = Meses.Dezembro &Ano.AddItem((&Ano+1),Str((&Ano+1),4,0)) endif endif
do 'MontarSemanas'
BtnWizardFirstPrevious.Visible = false
EndEvent
Event Refresh
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do 'CheckSecurityForActions'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event Enter
if &Semana = 0 &DataInicial.Set(&Ano,Meses.Convert(&Mes),1) &DataFinal = &DataInicial.EndOfMonth() else &DataInicial = &DataInicialCollection.Item(&Semana) &DataFinal = &DataFinalCollection.Item(&Semana) endif
// Valida data de envio if &DataEnvio < &DataInicial.AddDays(-7) msg('A data de envio não pode ser anterior a 7 dias do início do período informado.') &HasValidationErrors = true else &HasValidationErrors = false endif
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do 'CheckRequiredFields' If &CheckRequiredFieldsResult AND not &HasValidationErrors Do 'SaveVariablesToWizardData' WizardRanchoFixo(!'Periodo', !'Locais', false) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event 'WizardPrevious'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Return
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Sub 'CheckSecurityForActions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If not (not &GoingBack) BtnWizardFirstPrevious.Visible = False Endif
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadVariablesFromWizardData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//Code block: XmlFileToWizardData &WizardData.FromXML(FileXmlToWizardData(&WebSessionKey)) &WebSession.Set(&WebSessionKey,&WizardData.ToJson())
&WizardData.FromJson(&WebSession.Get(&WebSessionKey)) &DataInicial = &WizardData.Periodo.DataInicial &DataFinal = &WizardData.Periodo.DataFinal &DataEnvio = &WizardData.Periodo.DataEnvio &Mes = &WizardData.Periodo.Mes &Ano = &WizardData.Periodo.Ano &Semana = &WizardData.Periodo.Semana
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'SaveVariablesToWizardData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&WizardData.FromJson(&WebSession.Get(&WebSessionKey)) &WizardData.Periodo.DataInicial = &DataInicial &WizardData.Periodo.DataFinal = &DataFinal &WizardData.Periodo.DataEnvio = &DataEnvio &WizardData.Periodo.Mes = &Mes &WizardData.Periodo.Ano = &Ano &WizardData.Periodo.Semana = &Semana &WebSession.Set(&WebSessionKey, &WizardData.ToJson())
//Code block: WizardDataToXmlFile WizardDataToFileXML(&WebSessionKey,&WizardData.ToXml())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckRequiredFields'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&CheckRequiredFieldsResult = True If &DataEnvio.IsEmpty() Msg(DVMessageGetBasicNotificationMsg('', Format('WWP_RequiredAttribute','Data Envio'), DVMessageType.error, &DataEnvio.InternalName, DVMessageBoolean.True, '')) &CheckRequiredFieldsResult = False EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Event GlobalEvents.ForceUpdateWizardData
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//Code block: ForceUpdateWizardDataGlobalEvent do 'SaveVariablesToWizardData' do 'LoadVariablesFromWizardData'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event &Mes.ControlValueChanged
do 'MontarSemanas'
EndEvent
Event &Ano.Click
do 'MontarSemanas'
EndEvent
Sub 'MontarSemanas'
&DataInicialCollection.Clear() &DataFinalCollection.Clear() &Semana.Clear()
/* Data base */ &DataBase.Set(&Ano,Meses.Convert(&Mes),1)
/* Todas */ &Semana.AddItem(0,'Todas')
/* Semana 1 */ &DataInicial = &DataBase &DataFinal = &DataInicial.AddDays((7 - &DataInicial.DayOfWeek())) &DataInicialCollection.Add(&DataInicial) &DataFinalCollection.Add(&DataFinal) &Semana.AddItem(1,format('Semana 1 (%1 a %2)',&DataInicial.ToFormattedString(),&DataFinal.ToFormattedString()))
/* Semana 2 */ &DataInicial = &DataFinal.AddDays(1) &DataFinal = &DataInicial.AddDays((7 - &DataInicial.DayOfWeek())) &DataInicialCollection.Add(&DataInicial) &DataFinalCollection.Add(&DataFinal) &Semana.AddItem(2,format('Semana 2 (%1 a %2)',&DataInicial.ToFormattedString(),&DataFinal.ToFormattedString()))
/* Semana 3 */ &DataInicial = &DataFinal.AddDays(1) &DataFinal = &DataInicial.AddDays((7 - &DataInicial.DayOfWeek())) &DataInicialCollection.Add(&DataInicial) &DataFinalCollection.Add(&DataFinal) &Semana.AddItem(3,format('Semana 3 (%1 a %2)',&DataInicial.ToFormattedString(),&DataFinal.ToFormattedString()))
/* Semana 4 */ &DataInicial = &DataFinal.AddDays(1) &DataFinal = &DataInicial.AddDays((7 - &DataInicial.DayOfWeek())) if &DataFinal > &DataBase.EndOfMonth() &DataFinal = &DataBase.EndOfMonth() endif &DataInicialCollection.Add(&DataInicial) &DataFinalCollection.Add(&DataFinal) &Semana.AddItem(4,format('Semana 4 (%1 a %2)',&DataInicial.ToFormattedString(),&DataFinal.ToFormattedString()))
/* Semana 5 */ if &DataFinal < &DataBase.EndOfMonth() &DataInicial = &DataFinal.AddDays(1) &DataFinal = &DataInicial.AddDays((7 - &DataInicial.DayOfWeek())) if &DataFinal > &DataBase.EndOfMonth() &DataFinal = &DataBase.EndOfMonth() endif &DataInicialCollection.Add(&DataInicial) &DataFinalCollection.Add(&DataFinal) &Semana.AddItem(5,format('Semana 5 (%1 a %2)',&DataInicial.ToFormattedString(),&DataFinal.ToFormattedString())) else &DataInicial.SetEmpty() &DataFinal.SetEmpty() endif
/* Semana 6 */ if not &DataFinal.IsEmpty() and &DataFinal < &DataBase.EndOfMonth() &DataInicial = &DataFinal.AddDays(1) &DataFinal = &DataBase.EndOfMonth() &DataInicialCollection.Add(&DataInicial) &DataFinalCollection.Add(&DataFinal) &Semana.AddItem(6,format('Semana 6 (%1 a %2)',&DataInicial.ToFormattedString(),&DataFinal.ToFormattedString())) endif
&DataInicial.SetEmpty() &DataFinal.SetEmpty()
EndSub
